/**
 * kon-dms
 *
 * Sistema de gestión documental con versionado semántico, workflows de aprobación y trazabilidad completa
 */
export interface DmsApi {
  /**
   * Open a document by code
   *
   * 307 redirect to the reader view (/api/dms/render/<slug>) of the document with this code, if the caller can read it; 404 otherwise.
   *
   * REST: `GET /api/dms/render/code/{code}` · scope `kon:dms:abrir-documento-por-codigo`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly abrirDocumentoPorCodigo: Operation<AbrirDocumentoPorCodigoParams, AbrirDocumentoPorCodigoResponse>;
  /**
   * Archive a document
   *
   * Archives a document (soft delete: inactive and `archived`; nothing is erased). Owner or admin. 404 when the caller cannot read it, 403 when it may read but is not the owner.
   *
   * REST: `DELETE /api/dms/documents/{id}` · scope `kon:dms:archivar-documento`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `dms__archivar-documento`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly archivarDocumento: Operation<ArchivarDocumentoParams, ArchivarDocumentoResponse>;
  /**
   * Delete a comment
   *
   * Deletes a comment: its author, or whoever edits the document (moderation). 404 when the caller cannot see it.
   *
   * REST: `DELETE /api/dms/comments/{commentId}` · scope `kon:dms:borrar-comentario`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `dms__borrar-comentario`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly borrarComentario: Operation<BorrarComentarioParams, BorrarComentarioResponse>;
  /**
   * Delete a diagram
   *
   * Deletes a diagram of an editable version (owner or author; 409 when the version is no longer a draft).
   *
   * REST: `DELETE /api/dms/diagrams/{diagramId}` · scope `kon:dms:borrar-diagrama`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `dms__borrar-diagrama`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly borrarDiagrama: Operation<BorrarDiagramaParams, BorrarDiagramaResponse>;
  /**
   * Search documents
   *
   * Full-text search (Spanish) in the current published versions of the documents the caller can read, with a highlighted `snippet`; when nothing matches, falls back to title/code/description (`searchType: fallback`). Also returns up to 10 matching folders. `q` 2-200 characters (400 otherwise); filters `categoryId`, `type`, `status`; `limit` 1-50, default 20.
   *
   * REST: `GET /api/dms/search` · scope `kon:dms:buscar-documentos`
   * idempotent (safe to retry) · MCP tool `dms__buscar-documentos`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly buscarDocumentos: Operation<BuscarDocumentosParams, BuscarDocumentosResponse>;
  /**
   * Acknowledge reading a document
   *
   * Records that the caller has read the document's current published version (optional `notes`). Repeating it answers `{ alreadyAcknowledged: true }`. 409 when the document has no published version.
   *
   * REST: `POST /api/dms/documents/{id}/acknowledge` · scope `kon:dms:confirmar-lectura`
   * idempotent (safe to retry) · MCP tool `dms__confirmar-lectura`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly confirmarLectura: Operation<ConfirmarLecturaParams, ConfirmarLecturaResponse>;
  /**
   * Create a document folder
   *
   * Creates a folder (category). Admin only (403 otherwise): folders carry an ACL, `allowedRoles` = roles that may read the documents inside. `slug` defaults from the name; `parentId` must exist (422). Returns the folder (201); 409 when the slug is taken.
   *
   * REST: `POST /api/dms/categories` · scope `kon:dms:crear-carpeta`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__crear-carpeta`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearCarpeta: Operation<CrearCarpetaParams, CrearCarpetaResponse>;
  /**
   * Comment on a document
   *
   * Adds a comment to a document the caller can read, optionally on one of its versions the caller can see (`versionId`) or as a reply (`parentId`, a comment of the same document); otherwise 422. Returns the comment (201).
   *
   * REST: `POST /api/dms/documents/{id}/comments` · scope `kon:dms:crear-comentario`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__crear-comentario`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearComentario: Operation<CrearComentarioParams, CrearComentarioResponse>;
  /**
   * Add a diagram to a draft version
   *
   * Adds a diagram (source XML/JSON, rendered SVG or a media id) to a version in `draft` or `changes_requested` (owner or author; 409 otherwise). An SVG with executable code is refused (422). Embed it in the content as [[diagram:<id>]]. Returns the diagram (201).
   *
   * REST: `POST /api/dms/versions/{versionId}/diagrams` · scope `kon:dms:crear-diagrama`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__crear-diagrama`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearDiagrama: Operation<CrearDiagramaParams, CrearDiagramaResponse>;
  /**
   * Create a document
   *
   * Creates a document (metadata and ACL); with `content` or `changelog` also its first draft version 1.0.0. Team only (admin/editor; 403 otherwise). The owner is the caller (only an admin may set another `ownerId`); `visibility` defaults to `restricted`. HTML content with executable code is refused (422). Returns the document (201); 409 when `code` is taken.
   *
   * REST: `POST /api/dms/documents` · scope `kon:dms:crear-documento`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__crear-documento`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearDocumento: Operation<CrearDocumentoParams, CrearDocumentoResponse>;
  /**
   * Create a document from a template
   *
   * Copies a template document (one with `isTemplate`) the caller can read into a new PRIVATE document owned by the caller, with a draft 1.0.0 cloned from the latest template version the caller can see. Team only (admin/editor). Returns the new document (201); 404 when the template does not exist, is not a template or cannot be read.
   *
   * REST: `POST /api/dms/documents/from-template/{templateId}` · scope `kon:dms:crear-documento-desde-plantilla`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__crear-documento-desde-plantilla`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearDocumentoDesdePlantilla: Operation<CrearDocumentoDesdePlantillaParams, CrearDocumentoDesdePlantillaResponse>;
  /**
   * Relate two documents
   *
   * Links a document (owner or author) to another one the caller can read (`related`, `replaces`, `requires`, `supersedes`). A target the caller cannot read is a 422, never a 404 (no oracle). 409 when the relation already exists.
   *
   * REST: `POST /api/dms/documents/{id}/relations` · scope `kon:dms:crear-relacion`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__crear-relacion`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearRelacion: Operation<CrearRelacionParams, CrearRelacionResponse>;
  /**
   * Create a draft version
   *
   * Adds a draft version to a document (owner or author). The number is the next semantic version by `changeType` (major | minor | patch, default minor). HTML content with executable code is refused (422). Returns the version (201) with `warnings.wikiLinks` ([[code-or-slug]] links and whether each exists for the caller).
   *
   * REST: `POST /api/dms/documents/{id}/versions` · scope `kon:dms:crear-version`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__crear-version`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearVersion: Operation<CrearVersionParams, CrearVersionResponse>;
  /**
   * Download an attached file
   *
   * 302 redirect to a signed storage URL valid for 5 minutes. Follows its version: a draft's file only for owner, author, reviewers and approvers. Counts a download. 404 when the caller cannot see it.
   *
   * REST: `GET /api/dms/files/{fileId}/download` · scope `kon:dms:descargar-fichero`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly descargarFichero: Operation<DescargarFicheroParams, DescargarFicheroResponse>;
  /**
   * Edit a comment
   *
   * Changes the text of a comment. Only its author (403 otherwise); 404 when the caller cannot see it.
   *
   * REST: `PATCH /api/dms/comments/{commentId}` · scope `kon:dms:editar-comentario`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__editar-comentario`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarComentario: Operation<EditarComentarioParams, EditarComentarioResponse>;
  /**
   * Update a diagram
   *
   * Updates a diagram of an editable version (owner or author; 409 when the version is no longer a draft). An SVG with executable code is refused (422).
   *
   * REST: `PATCH /api/dms/diagrams/{diagramId}` · scope `kon:dms:editar-diagrama`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__editar-diagrama`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarDiagrama: Operation<EditarDiagramaParams, EditarDiagramaResponse>;
  /**
   * Update a document
   *
   * Updates a document's metadata. Owner or author; the ACL fields (owner, folder, reviewers, approvers, visibility, allowed users/roles) only the owner or an admin; `status` only an admin, or the owner to `archived`/`deprecated` (the workflow moves it otherwise). A new `slug` keeps the old one as a redirect. 404 when the caller cannot read it, 403 when it may read but not do this.
   *
   * REST: `PATCH /api/dms/documents/{id}` · scope `kon:dms:editar-documento`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__editar-documento`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarDocumento: Operation<EditarDocumentoParams, EditarDocumentoResponse>;
  /**
   * Update a draft version
   *
   * Updates the content, format or changelog of a version in `draft` or `changes_requested` (owner or author). A published version is immutable (409). HTML content with executable code is refused (422). Returns the version with `warnings.wikiLinks`.
   *
   * REST: `PATCH /api/dms/versions/{versionId}` · scope `kon:dms:editar-version`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__editar-version`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarVersion: Operation<EditarVersionParams, EditarVersionResponse>;
  /**
   * Submit a version for review
   *
   * Moves a `draft` or `changes_requested` version to `review_pending` and notifies the document's reviewers (owner or author; 409 in any other state).
   *
   * REST: `POST /api/dms/versions/{versionId}/submit` · scope `kon:dms:enviar-version-a-revision`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__enviar-version-a-revision`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly enviarVersionARevision: Operation<EnviarVersionARevisionParams, EnviarVersionARevisionResponse>;
  /**
   * Export a folder
   *
   * The published documents of a folder the caller can read, as a JSON manifest plus `files` (`<slug>/metadata.json` and `<slug>/content.md` per document); the same shape importar-documentos takes. 404 when the folder does not exist or is not visible.
   *
   * REST: `GET /api/dms/categories/{id}/export/zip` · scope `kon:dms:exportar-carpeta`
   * idempotent (safe to retry) · MCP tool `dms__exportar-carpeta`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly exportarCarpeta: Operation<ExportarCarpetaParams, ExportarCarpetaResponse>;
  /**
   * Export a version as HTML
   *
   * A standalone HTML page of the version (markdown/raw content escaped inside <pre>), served with a sandbox Content-Security-Policy. Same visibility as ver-version.
   *
   * REST: `GET /api/dms/versions/{versionId}/export/html` · scope `kon:dms:exportar-version-html`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly exportarVersionHtml: Operation<ExportarVersionHtmlParams, ExportarVersionHtmlResponse>;
  /**
   * Export a version as Markdown
   *
   * The version's content as a Markdown attachment (other formats are prefixed with a comment naming the original format). Same visibility as ver-version.
   *
   * REST: `GET /api/dms/versions/{versionId}/export/md` · scope `kon:dms:exportar-version-markdown`
   * idempotent (safe to retry) · MCP tool `dms__exportar-version-markdown`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly exportarVersionMarkdown: Operation<ExportarVersionMarkdownParams, ExportarVersionMarkdownResponse>;
  /**
   * Import documents
   *
   * Imports the output of exportar-carpeta: one PRIVATE draft document per `<slug>/metadata.json` (owned by the caller), with a draft 1.0.0 from its `content.md`. Team only (admin/editor). Files that fail are listed in `results.errors` (invalid JSON, code taken); the rest are imported.
   *
   * REST: `POST /api/dms/import` · scope `kon:dms:importar-documentos`
   * not idempotent (an Idempotency-Key is sent automatically) · sensitive: may come back as a proposal pending human approval · MCP tool `dms__importar-documentos`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly importarDocumentos: Operation<ImportarDocumentosParams, ImportarDocumentosResponse>;
  /**
   * Read a published document
   *
   * The reader view of a document by slug: its current published version with header ids, embedded diagrams, table of contents, wiki-link check, breadcrumb and previous/next documents of the same folder. An old slug answers 308 to the current one (only for a document the caller can read). 404 when it does not exist, is not readable or has no published version.
   *
   * REST: `GET /api/dms/render/{slug}` · scope `kon:dms:leer-documento`
   * idempotent (safe to retry) · MCP tool `dms__leer-documento`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly leerDocumento: Operation<LeerDocumentoParams, LeerDocumentoResponse>;
  /**
   * My workflow notifications
   *
   * The caller's own workflow notifications (review requested, approved, changes requested, published), newest first, paginated. `unreadOnly=true` filters.
   *
   * REST: `GET /api/dms/notifications` · scope `kon:dms:listar-avisos`
   * idempotent (safe to retry) · MCP tool `dms__listar-avisos`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarAvisos: PageableOperation<ListarAvisosParams, ListarAvisosResponse, ListarAvisosItem>;
  /**
   * List document folders
   *
   * Active folders (categories) the caller can see, ordered by sortOrder and name. The team (admin/editor) sees every folder; any other account sees the folders opened to its role and those holding a document it can read. `parentId` filters by parent (`null` = top level; a value that is not a uuid gives an empty list); `stats=true` adds `documentCount` (published documents the caller can read).
   *
   * REST: `GET /api/dms/categories` · scope `kon:dms:listar-carpetas`
   * idempotent (safe to retry) · MCP tool `dms__listar-carpetas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarCarpetas: Operation<ListarCarpetasParams, ListarCarpetasResponse>;
  /**
   * List a document's comments
   *
   * Top-level comments of a document with their `replies`, oldest first, paginated (`limit` 1-100, `page`). `resolved=true|false` filters. Readers do not see comments made on versions they cannot see.
   *
   * REST: `GET /api/dms/documents/{id}/comments` · scope `kon:dms:listar-comentarios`
   * idempotent (safe to retry) · MCP tool `dms__listar-comentarios`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarComentarios: PageableOperation<ListarComentariosParams, ListarComentariosResponse, ListarComentariosItem>;
  /**
   * Who acknowledged a document
   *
   * The reading acknowledgments of a document, newest first. Owner or author (403 for a mere reader).
   *
   * REST: `GET /api/dms/documents/{id}/acknowledgments` · scope `kon:dms:listar-confirmaciones-de-lectura`
   * idempotent (safe to retry) · MCP tool `dms__listar-confirmaciones-de-lectura`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarConfirmacionesDeLectura: Operation<ListarConfirmacionesDeLecturaParams, ListarConfirmacionesDeLecturaResponse>;
  /**
   * List a version's diagrams
   *
   * The diagrams embedded in a version, by name. Same visibility as ver-version.
   *
   * REST: `GET /api/dms/versions/{versionId}/diagrams` · scope `kon:dms:listar-diagramas`
   * idempotent (safe to retry) · MCP tool `dms__listar-diagramas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarDiagramas: Operation<ListarDiagramasParams, ListarDiagramasResponse>;
  /**
   * List documents
   *
   * Active documents the caller can read (owner, author, reviewer, approver, shared by user/role/folder, or published public/internal), newest update first, paginated (`limit` 1-100, default 50; `page`). Filters: `categoryId`, `status`, `type`, `ownerId`, `tags` (comma-separated, all required) and `search` (title, code, description). Each row adds `requiresReview` and `categoryName`. Metadata only: the content is in the versions.
   *
   * REST: `GET /api/dms/documents` · scope `kon:dms:listar-documentos`
   * idempotent (safe to retry) · MCP tool `dms__listar-documentos`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarDocumentos: PageableOperation<ListarDocumentosParams, ListarDocumentosResponse, ListarDocumentosItem>;
  /**
   * Documents linking to this one
   *
   * Active documents the caller can read whose published content links to this document as [[code]] or [[slug]].
   *
   * REST: `GET /api/dms/documents/{id}/backlinks` · scope `kon:dms:listar-enlaces-entrantes`
   * idempotent (safe to retry) · MCP tool `dms__listar-enlaces-entrantes`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarEnlacesEntrantes: Operation<ListarEnlacesEntrantesParams, ListarEnlacesEntrantesResponse>;
  /**
   * List a document's versions
   *
   * The versions of a document, newest first, with their content. Readers only get published versions; owner, author, reviewers and approvers get drafts too. 404 when the caller cannot read the document.
   *
   * REST: `GET /api/dms/documents/{id}/versions` · scope `kon:dms:listar-versiones`
   * idempotent (safe to retry) · MCP tool `dms__listar-versiones`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarVersiones: Operation<ListarVersionesParams, ListarVersionesResponse>;
  /**
   * Mark a notification as read
   *
   * Marks one of the caller's notifications as read. 404 when it is not the caller's.
   *
   * REST: `POST /api/dms/notifications/{id}/read` · scope `kon:dms:marcar-aviso-leido`
   * idempotent (safe to retry) · MCP tool `dms__marcar-aviso-leido`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly marcarAvisoLeido: Operation<MarcarAvisoLeidoParams, MarcarAvisoLeidoResponse>;
  /**
   * Mark all my notifications as read
   *
   * Marks every unread notification of the caller as read.
   *
   * REST: `POST /api/dms/notifications/read-all` · scope `kon:dms:marcar-avisos-leidos`
   * idempotent (safe to retry) · MCP tool `dms__marcar-avisos-leidos`
   * Errors: `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly marcarAvisosLeidos: Operation<void, MarcarAvisosLeidosResponse>;
  /**
   * Publish an approved version
   *
   * Publishes an `approved` version: it becomes the document's current version, the document becomes `published` and author and owner are notified. Approvers or the owner. 409 when the version is not approved.
   *
   * REST: `POST /api/dms/versions/{versionId}/publish` · scope `kon:dms:publicar-version`
   * not idempotent (an Idempotency-Key is sent automatically) · sensitive: may come back as a proposal pending human approval · MCP tool `dms__publicar-version`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly publicarVersion: Operation<PublicarVersionParams, PublicarVersionResponse>;
  /**
   * Resolve a comment
   *
   * Marks a comment as resolved: its author, or whoever edits the document. Returns the comment.
   *
   * REST: `POST /api/dms/comments/{commentId}/resolve` · scope `kon:dms:resolver-comentario`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__resolver-comentario`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly resolverComentario: Operation<ResolverComentarioParams, ResolverComentarioResponse>;
  /**
   * Review a version
   *
   * Approves a `review_pending` version or requests changes (`decision`, optional `notes`), and notifies author and owner. Reviewers and approvers of the document who are on the team (admin/editor); never the version's author nor the document's owner (except an admin). 409 when it is not pending review.
   *
   * REST: `POST /api/dms/versions/{versionId}/review` · scope `kon:dms:revisar-version`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `dms__revisar-version`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly revisarVersion: Operation<RevisarVersionParams, RevisarVersionResponse>;
  /**
   * Attach a file to a draft version
   *
   * Uploads one file (multipart field `file`, up to 25 MB) to a version in `draft` or `changes_requested` (owner or author; 409 otherwise). Office documents, PDF, ZIP, text, CSV, Markdown and raster images only (HTML, SVG, scripts: 422). The client's file name is only displayed, never used as the storage key. Returns the file row (201), without its storage location.
   *
   * REST: `POST /api/dms/versions/{versionId}/files` · scope `kon:dms:subir-fichero`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly subirFichero: Operation<SubirFicheroParams, SubirFicheroResponse>;
  /**
   * Folder tree
   *
   * The folders the caller can see as a tree (`docs`: top-level folders, each with `children`). A folder whose parent the caller cannot see hangs from the top level.
   *
   * REST: `GET /api/dms/categories/tree` · scope `kon:dms:ver-arbol-de-carpetas`
   * idempotent (safe to retry) · MCP tool `dms__ver-arbol-de-carpetas`
   * Errors: `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verArbolDeCarpetas: Operation<void, VerArbolDeCarpetasResponse>;
  /**
   * Audit log
   *
   * Access and change log, newest first, paginated (`limit` 1-100, `page`). The whole log: admin only; anyone else must pass `documentId` of a document they own or authored (403 otherwise). Filters: `documentId`, `userId`, `action`.
   *
   * REST: `GET /api/dms/audit-log` · scope `kon:dms:ver-auditoria`
   * idempotent (safe to retry) · MCP tool `dms__ver-auditoria`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verAuditoria: PageableOperation<VerAuditoriaParams, VerAuditoriaResponse, VerAuditoriaItem>;
  /**
   * Get a document
   *
   * A document the caller can read, with `requiresReview` and its `category`. `versions=true` adds its versions (readers: only published ones) and `currentVersion`; `relations=true` adds the relations to documents the caller can read. Readers do not get the ACL fields. Counts a view. 404 when it does not exist or the caller cannot read it.
   *
   * REST: `GET /api/dms/documents/{id}` · scope `kon:dms:ver-documento`
   * idempotent (safe to retry) · MCP tool `dms__ver-documento`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verDocumento: Operation<VerDocumentoParams, VerDocumentoResponse>;
  /**
   * DMS statistics
   *
   * Counts over the documents the caller can read: by status, versions and stored bytes, by type, the reviews due in the next 30 days and how many versions are pending the caller's review (admin: all).
   *
   * REST: `GET /api/dms/stats` · scope `kon:dms:ver-estadisticas`
   * idempotent (safe to retry) · MCP tool `dms__ver-estadisticas`
   * Errors: `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verEstadisticas: Operation<void, VerEstadisticasResponse>;
  /**
   * Get a version
   *
   * A version with its content. Published versions: anyone who can read the document; drafts: owner, author, reviewers and approvers (404 otherwise). `files=true` adds its attached files (without storage location).
   *
   * REST: `GET /api/dms/versions/{versionId}` · scope `kon:dms:ver-version`
   * idempotent (safe to retry) · MCP tool `dms__ver-version`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verVersion: Operation<VerVersionParams, VerVersionResponse>;
}
